-- Trooferz Sports Club Schema
-- Compatible with local MySQL and cloud MySQL services (Aiven, Render, PlanetScale, AWS RDS)
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS admin_logs,notifications,announcements,offers,memberships,membership_plans,bookings,blocked_slots,time_slots,facilities,sports,users,roles;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE roles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(20) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,mobile VARCHAR(30) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('USER','ADMIN') NOT NULL DEFAULT 'USER',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_users_role_active(role,is_active)) ENGINE=InnoDB;
CREATE TABLE sports(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description TEXT,image_url VARCHAR(500),price DECIMAL(10,2) NOT NULL DEFAULT 0,duration_minutes INT UNSIGNED NOT NULL DEFAULT 60,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE facilities(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,sport_id INT UNSIGNED NOT NULL,capacity INT UNSIGNED NOT NULL DEFAULT 1,price DECIMAL(10,2) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,description TEXT,image_url VARCHAR(500),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_facilities_sport FOREIGN KEY(sport_id) REFERENCES sports(id) ON UPDATE CASCADE ON DELETE RESTRICT,INDEX idx_facilities_sport_active(sport_id,is_active)) ENGINE=InnoDB;
CREATE TABLE time_slots(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,facility_id INT UNSIGNED NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,is_available TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_facility_time(facility_id,start_time,end_time),CONSTRAINT fk_slots_facility FOREIGN KEY(facility_id) REFERENCES facilities(id) ON UPDATE CASCADE ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE blocked_slots(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,blocked_date DATE NOT NULL,time_slot_id INT UNSIGNED NOT NULL,reason VARCHAR(255) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_blocked_slot_date(blocked_date,time_slot_id),CONSTRAINT fk_blocked_slot FOREIGN KEY(time_slot_id) REFERENCES time_slots(id) ON UPDATE CASCADE ON DELETE CASCADE,INDEX idx_blocked_date(blocked_date)) ENGINE=InnoDB;
CREATE TABLE bookings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_code VARCHAR(40) NOT NULL UNIQUE,user_id INT UNSIGNED NOT NULL,sport_id INT UNSIGNED NOT NULL,facility_id INT UNSIGNED NOT NULL,time_slot_id INT UNSIGNED NOT NULL,booking_date DATE NOT NULL,status ENUM('PENDING','CONFIRMED','CANCELLED','COMPLETED') NOT NULL DEFAULT 'PENDING',amount DECIMAL(10,2) NOT NULL DEFAULT 0,active_slot_key VARCHAR(80) GENERATED ALWAYS AS (CASE WHEN status IN ('PENDING','CONFIRMED') THEN CONCAT(facility_id,'/',time_slot_id,'/',booking_date) ELSE NULL END) VIRTUAL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_booking_user FOREIGN KEY(user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE RESTRICT,CONSTRAINT fk_booking_sport FOREIGN KEY(sport_id) REFERENCES sports(id) ON UPDATE CASCADE ON DELETE RESTRICT,CONSTRAINT fk_booking_facility FOREIGN KEY(facility_id) REFERENCES facilities(id) ON UPDATE CASCADE ON DELETE RESTRICT,CONSTRAINT fk_booking_slot FOREIGN KEY(time_slot_id) REFERENCES time_slots(id) ON UPDATE CASCADE ON DELETE RESTRICT,UNIQUE KEY uq_active_booking_slot(active_slot_key),INDEX idx_booking_date(booking_date),INDEX idx_booking_user(user_id),INDEX idx_booking_filters(sport_id,facility_id,status)) ENGINE=InnoDB;
CREATE TABLE membership_plans(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,price DECIMAL(10,2) NOT NULL,duration_days INT UNSIGNED NOT NULL,benefits TEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE memberships(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,plan_id INT UNSIGNED NOT NULL,start_date DATETIME NOT NULL,end_date DATETIME NOT NULL,status ENUM('ACTIVE','EXPIRED','CANCELLED') NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_membership_user FOREIGN KEY(user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE RESTRICT,CONSTRAINT fk_membership_plan FOREIGN KEY(plan_id) REFERENCES membership_plans(id) ON UPDATE CASCADE ON DELETE RESTRICT,INDEX idx_membership_status(status,end_date),INDEX idx_membership_user(user_id)) ENGINE=InnoDB;
CREATE TABLE notifications(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,title VARCHAR(150) NOT NULL,message VARCHAR(1000) NOT NULL,type ENUM('BOOKING','MEMBERSHIP','ANNOUNCEMENT','SYSTEM') NOT NULL DEFAULT 'SYSTEM',is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE CASCADE,INDEX idx_notification_user(user_id,is_read,created_at)) ENGINE=InnoDB;
CREATE TABLE offers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,description TEXT,discount_percent DECIMAL(5,2) NOT NULL DEFAULT 0,valid_until DATE NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE announcements(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,message TEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE admin_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_user_id INT UNSIGNED NOT NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,details JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_admin_log_user FOREIGN KEY(admin_user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE RESTRICT,INDEX idx_admin_log_created(created_at)) ENGINE=InnoDB;
INSERT INTO roles(name) VALUES('USER'),('ADMIN');
